#include <math.h>
static id<MTLDevice> dev;
static void need(BOOL ok,NSString*s){if(!ok){fprintf(stderr,"FAIL %s\n",s.UTF8String);exit(1);}}
static id<MTLLibrary> load(NSString*p,NSString*extra){NSError*e=nil;NSString*s=[NSString stringWithContentsOfFile:p encoding:NSUTF8StringEncoding error:&e];need(s!=nil,e.description);MTLCompileOptions*o=[MTLCompileOptions new];o.languageVersion=MTLLanguageVersion3_0;o.mathMode=MTLMathModeFast;id<MTLLibrary>l=[dev newLibraryWithSource:[s stringByAppendingString:extra]options:o error:&e];need(l!=nil,e.description);return l;}
static id<MTLTexture> tex(int w,int h){MTLTextureDescriptor*d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:MTLPixelFormatRGBA16Float width:w height:h mipmapped:NO];d.storageMode=MTLStorageModeShared;d.usage=MTLTextureUsageShaderRead|MTLTextureUsageShaderWrite|MTLTextureUsageRenderTarget;return[dev newTextureWithDescriptor:d];}
static id<MTLRenderPipelineState> renderPipeline(id<MTLLibrary>l,NSString*vs,NSString*fs){NSError*e=nil;MTLRenderPipelineDescriptor*d=[MTLRenderPipelineDescriptor new];d.vertexFunction=[l newFunctionWithName:vs];d.fragmentFunction=[l newFunctionWithName:fs];d.colorAttachments[0].pixelFormat=MTLPixelFormatRGBA16Float;id<MTLRenderPipelineState>p=[dev newRenderPipelineStateWithDescriptor:d error:&e];need(p!=nil,e.description);return p;}
static void done(id<MTLCommandBuffer>c){[c commit];[c waitUntilCompleted];need(c.status==MTLCommandBufferStatusCompleted,c.error.description);}
static void pass(id<MTLCommandQueue>q,id<MTLRenderPipelineState>p,id<MTLTexture>o,NSArray*inputs,id<MTLBuffer>f,id<MTLBuffer>l,id<MTLBuffer>g,const void*params){id<MTLCommandBuffer>c=[q commandBuffer];MTLRenderPassDescriptor*d=[MTLRenderPassDescriptor renderPassDescriptor];d.colorAttachments[0].texture=o;d.colorAttachments[0].loadAction=MTLLoadActionDontCare;d.colorAttachments[0].storeAction=MTLStoreActionStore;id<MTLRenderCommandEncoder>e=[c renderCommandEncoderWithDescriptor:d];[e setRenderPipelineState:p];[e setFragmentBuffer:f offset:0 atIndex:16];[e setFragmentBuffer:l offset:0 atIndex:17];[e setFragmentBuffer:g offset:0 atIndex:18];if(params)[e setFragmentBytes:params length:16 atIndex:0];for(int i=0;i<inputs.count;i++)[e setFragmentTexture:inputs[i]atIndex:i];[e drawPrimitives:MTLPrimitiveTypeTriangle vertexStart:0 vertexCount:3];[e endEncoding];done(c);}
static void png(NSString*path,const float*v,int W,int H){NSMutableData*d=[NSMutableData dataWithLength:W*H*4];uint8_t*b=d.mutableBytes;for(int i=0;i<W*H;i++){for(int k=0;k<3;k++){float x=fminf(1,fmaxf(0,v[i*4+k]/4));float s=x<=.0031308?12.92*x:1.055*powf(x,1/2.4)-.055;b[4*i+k]=lrintf(255*s);}b[4*i+3]=255;}CGColorSpaceRef cs=CGColorSpaceCreateWithName(kCGColorSpaceSRGB);CGContextRef ctx=CGBitmapContextCreate(b,W,H,8,W*4,cs,(CGBitmapInfo)kCGImageAlphaNoneSkipLast);CGImageRef im=CGBitmapContextCreateImage(ctx);CGImageDestinationRef dst=CGImageDestinationCreateWithURL((__bridge CFURLRef)[NSURL fileURLWithPath:path],(__bridge CFStringRef)UTTypePNG.identifier,1,NULL);CGImageDestinationAddImage(dst,im,NULL);need(CGImageDestinationFinalize(dst),@"png");CFRelease(dst);CGImageRelease(im);CGContextRelease(ctx);CGColorSpaceRelease(cs);}
static float lum(const float*p){return .2126*p[0]+.7152*p[1]+.0722*p[2];}
int main(int argc,const char**argv){@autoreleasepool{
 need(argc==3,@"fixture directory and probe");NSString*dir=@(argv[1]);dev=MTLCreateSystemDefaultDevice();need(dev!=nil,@"Metal device");NSError*err=nil;NSString*probe=[NSString stringWithContentsOfFile:@(argv[2])encoding:NSUTF8StringEncoding error:&err];need(probe!=nil,err.description);id<MTLLibrary>l=load([dir stringByAppendingPathComponent:@"post.metal"],probe),ll=load([dir stringByAppendingPathComponent:@"lut.metal"],@"");id<MTLCommandQueue>q=[dev newCommandQueue];
 id<MTLComputePipelineState>input=[dev newComputePipelineStateWithFunction:[l newFunctionWithName:@"sunInput"]error:&err],output=[dev newComputePipelineStateWithFunction:[l newFunctionWithName:@"sunOutput"]error:&err];need(input&&output,err.description);
 id<MTLRenderPipelineState>lutP=renderPipeline(ll,@"shade_lut_vs",@"shade_lut_fs"),down0=renderPipeline(l,@"shade_fs_vs",@"shade_bloom_down0"),down=renderPipeline(l,@"shade_fs_vs",@"shade_bloom_down"),up=renderPipeline(l,@"shade_fs_vs",@"shade_bloom_up");
 MTLSamplerDescriptor*sd=[MTLSamplerDescriptor new];sd.minFilter=sd.magFilter=MTLSamplerMinMagFilterLinear;sd.sAddressMode=sd.tAddressMode=MTLSamplerAddressModeClampToEdge;id<MTLSamplerState>sampler=[dev newSamplerStateWithDescriptor:sd];NSMutableDictionary*metrics=[NSMutableDictionary new];
 for(NSNumber*angle in @[@0,@65,@85]){
  NSData*u=[NSData dataWithContentsOfFile:[dir stringByAppendingPathComponent:[NSString stringWithFormat:@"%@.bin",angle]]];need(u.length==2240||u.length==2208,@"fixture layout");int lookSize=(int)u.length-1024-96;
  id<MTLBuffer>f=[dev newBufferWithBytes:u.bytes length:1024 options:0],look=[dev newBufferWithBytes:(char*)u.bytes+1024 length:lookSize options:0],g=[dev newBufferWithLength:512 options:0];memset(g.contents,0,512);float params[24];memcpy(params,(char*)u.bytes+1024+lookSize,96);
  const int W=1024,H=1024;id<MTLTexture>scene=tex(W,H),lut=tex(128,80),mw=tex(1,1);pass(q,lutP,lut,@[],f,look,g,NULL);
  id<MTLCommandBuffer>c=[q commandBuffer];id<MTLComputeCommandEncoder>e=[c computeCommandEncoder];[e setComputePipelineState:input];[e setBuffer:f offset:0 atIndex:16];[e setBuffer:look offset:0 atIndex:17];[e setTexture:scene atIndex:0];[e setTexture:lut atIndex:1];[e setTexture:mw atIndex:2];[e setSamplerState:sampler atIndex:13];[e dispatchThreads:MTLSizeMake(W,H,1)threadsPerThreadgroup:MTLSizeMake(8,8,1)];[e endEncoding];done(c);
  id<MTLTexture>levels[6],accum[6];float weights[6],sum=0;for(int i=0;i<6;i++){levels[i]=tex(W>>(i+1),H>>(i+1));accum[i]=tex(W>>(i+1),H>>(i+1));weights[i]=powf(i+1,.6);sum+=weights[i];}
  float dp[4]={1,1,0,0};pass(q,down0,levels[0],@[scene],f,look,g,dp);for(int i=1;i<6;i++)pass(q,down,levels[i],@[levels[i-1]],f,look,g,NULL);
  for(int i=5;i>=1;i--){float p[4]={weights[i]/sum,i==5?0:1,0,0};pass(q,up,accum[i],@[levels[i],i==5?levels[i]:accum[i+1]],f,look,g,p);}params[4]=weights[0]/sum;
  id<MTLBuffer>image=[dev newBufferWithLength:W*H*16 options:0];c=[q commandBuffer];e=[c computeCommandEncoder];[e setComputePipelineState:output];[e setBuffer:image offset:0 atIndex:1];[e setBytes:params length:96 atIndex:0];[e setBuffer:look offset:0 atIndex:17];[e setTexture:scene atIndex:0];[e setTexture:accum[1]atIndex:1];[e setTexture:levels[0]atIndex:2];[e dispatchThreads:MTLSizeMake(W,H,1)threadsPerThreadgroup:MTLSizeMake(8,8,1)];[e endEncoding];done(c);
  const float*v=image.contents;png([dir stringByAppendingPathComponent:[NSString stringWithFormat:@"%@.png",angle]],v,W,H);float peak=lum(v+4*((H/2)*W+W/2)),step=0,previous=peak;NSMutableArray*profile=[NSMutableArray new];
  for(int x=0;x<150;x++){float y=0;for(int sign=-1;sign<=1;sign+=2){y+=lum(v+4*((H/2)*W+W/2+sign*x));y+=lum(v+4*((H/2+sign*x)*W+W/2));}y*=.25;step=fmaxf(step,previous-y);previous=y;[profile addObject:@(y)];need(isfinite(y)&&y>=0,@"finite HDR profile");}
  metrics[angle.stringValue]=@{@"peak":@(peak),@"maximumPixelDrop":@(step),@"profile":profile};printf("sun %d: HDR peak %.4f, maximum radial step %.5f\n",angle.intValue,peak,step);
 }
 const char*baseline=getenv("SUNCHECK_BASELINE");if(baseline){NSDictionary*old=[NSJSONSerialization JSONObjectWithData:[NSData dataWithContentsOfFile:[@(baseline) stringByAppendingPathComponent:@"metrics.json"]]options:0 error:nil];need(old!=nil,@"baseline metrics");for(NSString*angle in metrics){float peak=[metrics[angle][@"peak"]floatValue],previous=[old[angle][@"peak"]floatValue];need(peak>=previous*.95&&peak<=previous*1.05,@"sun remains prominent in HDR");need([metrics[angle][@"maximumPixelDrop"]floatValue]<[old[angle][@"maximumPixelDrop"]floatValue]*.65,@"visible HDR core-to-halo transition must soften");}printf("PASS final HDR profile: softer transition and preserved peak brightness\n");}
 [[NSJSONSerialization dataWithJSONObject:metrics options:NSJSONWritingPrettyPrinted error:nil]writeToFile:[dir stringByAppendingPathComponent:@"metrics.json"]atomically:YES];
}return 0;}
